-- tp:non-transactional
-- 008/FR-027, US4 scenario 4 (PR #515 QA finding 1): `?state=X` must read tenders_open_state_idx. On (state) alone the
-- planner chose tenders_open_created_idx + filter for the page query and BitmapAnd(tenders_state_idx,
-- tenders_open_closing_idx) for count/facets. Rebuilt as (state, created_at DESC, coalesce(end_at, 'infinity')) so the
-- page query is an ordered index range and count/facets a single bitmap scan. Generated by drizzle-kit, hand-edited
-- (ADR-0013 exception): marker line, CONCURRENTLY. The name is kept (spec US4 scenario 4 names it), so the old index is
-- dropped first; until the rebuild finishes `?state=` falls back to the plans above (correct, ~30 ms at 500k).
-- Idempotent: a re-run drops whatever tenders_open_state_idx exists and rebuilds the new shape.
DROP INDEX CONCURRENTLY IF EXISTS "tenders_open_state_idx";--> statement-breakpoint
CREATE INDEX CONCURRENTLY IF NOT EXISTS "tenders_open_state_idx" ON "tenders" USING btree ("state","created_at" DESC NULLS FIRST,coalesce("end_at", 'infinity'::timestamptz)) WHERE status = 'open';
